-- «دفتر کلاسی — گزارش جلسه» (owner request, 2026-10-20; docs/decisions.md, docs/db.md academic.session_report).
-- Additive only: one new tenant table, nothing existing is changed. The table is generated by drizzle-kit below
-- (src/db/schema/academic.ts `sessionReport`); this file adds, after it:
-- 1) defense in depth for "never DELETE": a RESTRICTIVE DELETE policy for app_rw whose USING is false, ANDed with
--    tenant_isolation_delete — a DELETE as app_rw matches no row (a report is cleared by status = 'archived' +
--    archived_at, the app never deletes). It is a policy and NOT a REVOKE inside app.apply_grants() on purpose: this
--    migration does not redefine apply_grants (the REVOKE DELETE line can join the next migration that has to touch the
--    function anyway). Seeds and the pilot reset run as app_owner and pg_dump as app_backup — the policy is TO app_rw
--    only. apply_rls() never drops policies of other names.
-- 2) the three apply_* calls (grants, tenant RLS ENABLE + FORCE, the updated_at trigger) for the new table.
CREATE TABLE "academic"."session_report" (
	"id" uuid PRIMARY KEY NOT NULL,
	"organization_id" uuid NOT NULL,
	"class_group_id" uuid NOT NULL,
	"class_offering_id" uuid NOT NULL,
	"date" date NOT NULL,
	"period_no" smallint NOT NULL,
	"topic" text NOT NULL,
	"page_ref" text,
	"work_item_id" uuid,
	"private_note" text,
	"next_plan" text,
	"status" text DEFAULT 'active' NOT NULL,
	"archived_at" timestamp with time zone,
	"author_person_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "session_report_cell_uq" UNIQUE("organization_id","class_group_id","date","period_no"),
	CONSTRAINT "session_report_org_id_uq" UNIQUE("organization_id","id"),
	CONSTRAINT "session_report_period_chk" CHECK ("academic"."session_report"."period_no" BETWEEN 1 AND 12),
	CONSTRAINT "session_report_topic_chk" CHECK (char_length("academic"."session_report"."topic") BETWEEN 1 AND 200),
	CONSTRAINT "session_report_page_ref_chk" CHECK ("academic"."session_report"."page_ref" IS NULL OR char_length("academic"."session_report"."page_ref") BETWEEN 1 AND 100),
	CONSTRAINT "session_report_private_note_chk" CHECK ("academic"."session_report"."private_note" IS NULL OR char_length("academic"."session_report"."private_note") BETWEEN 1 AND 1000),
	CONSTRAINT "session_report_next_plan_chk" CHECK ("academic"."session_report"."next_plan" IS NULL OR char_length("academic"."session_report"."next_plan") BETWEEN 1 AND 300),
	CONSTRAINT "session_report_status_chk" CHECK ("academic"."session_report"."status" IN ('active', 'archived')),
	CONSTRAINT "session_report_archived_chk" CHECK (("academic"."session_report"."status" = 'archived') = ("academic"."session_report"."archived_at" IS NOT NULL))
);
